<# .SYNOPSIS     Detection script for Lenovo bloatware Remediation (Intune). .DESCRIPTION     Exit 1  = bloatware still present  -> remediation runs     Exit 0  = clean                    -> nothing to do     Targets: Lenovo Now, Lenovo Vantage (AppX) + Lenovo Vantage Service.     Deliberately IGNORES 'Lenovo Smart Meeting Components' (camera/AV effects - kept). #>  $ErrorActionPreference = 'SilentlyContinue'  # Classic installs we want gone (exact DisplayName match, case-insensitive) $targetNames = @('Lenovo Now', 'Lenovo Vantage Service')  $roots = @(     'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',     'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' )  $classicFound = Get-ItemProperty $roots |     Where-Object { $targetNames -contains $_.DisplayName }  # Vantage frontend AppX $appxFound = Get-AppxPackage -AllUsers -Name 'E046963F.LenovoCompanion' $provFound = Get-AppxProvisionedPackage -Online |     Where-Object { $_.DisplayName -like '*LenovoCompanion*' }  if ($classicFound -or $appxFound -or $provFound) {     Write-Output "Lenovo bloatware present - remediation needed."     exit 1 } else {     Write-Output "No targeted Lenovo bloatware found."     exit 0 }